    'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?w=800&q=85'
  ];
  function hash(s) { var h = 0; for (var i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) >>> 0; } return h; }
  function rng(seed) { var x = seed || 1; return function () { x = (x * 1103515245 + 12345) >>> 0; return (x >>> 8) / 16777216; }; }
  var AREAS = { 'Apartment': [110, 220], 'Duplex': [200, 320], 'Twin House': [250, 340], 'Townhouse': [220, 300], 'Penthouse': [240, 380], 'Villa': [350, 620] };
  var MULT = { 'Apartment': 0.32, 'Duplex': 0.5, 'Twin House': 0.62, 'Townhouse': 0.55, 'Penthouse': 0.75, 'Villa': 1 };

  D.unitsFor = function (name) {
    if (cache[name]) return cache[name];
    var c = D.compounds.find(function (x) { return x.n === name; });
    if (!c) return [];
    var r = rng(hash(name));
    var count = 8 + Math.floor(r() * 17); // 8–24 units
    var abbr = name.replace(/\(.*\)/, '').trim().split(/\s+/).map(function (w) { return w[0]; }).join('').toUpperCase().slice(0, 3);
    var units = [];
    for (var i = 0; i < count; i++) {
      var type = TYPES[Math.floor(r() * TYPES.length)];
      var span = AREAS[type];
      var area = Math.round((span[0] + r() * (span[1] - span[0])) / 5) * 5;
      var mode = r() < 0.3 ? 'rent' : 'sale';
