      var bath = Math.max(2, beds - Math.floor(r() * 2));
      var egpM = Math.round(c.priceM * MULT[type] * (0.85 + r() * 0.5) * 10) / 10;
      var usd = Math.round(c.rent * MULT[type] * (0.85 + r() * 0.5) / 50) * 50;
      var ai = Math.round(Math.min(9.9, Math.max(7.8, c.ai + (r() - 0.5) * 0.8)) * 10) / 10;
      var floor = type === 'Villa' || type === 'Twin House' || type === 'Townhouse' ? 'G+2' : (1 + Math.floor(r() * 8)) + '';
      units.push({
        code: abbr + '-' + type.charAt(0) + (101 + i),
        type: type, beds: beds, bath: bath, area: area, floor: floor,
        mode: mode, egpM: egpM, usd: usd, ai: ai,
        status: r() < 0.14 ? 'reserved' : 'available',
        delivery: r() < 0.65 ? 'ready' : 'under_construction',
        agent: AGENTS[Math.floor(r() * AGENTS.length)],
        img: IMGS[Math.floor(r() * IMGS.length)]
      });
    }
    cache[name] = units;
    return units;
  };
})(window.HZDATA);

/* Sierra Estates × Houzez portal — shared styles (light default + dark remix) */
:root{
  --pri:#00aeff;
  --pri-d:#0098e0;
  --pri-soft:#e9f8ff;
  --navy:#002b4b;
  --ink:#0d2136;
  --text:#5f7183;
  --muted:#9aa4ad;
  --line:#e7ebee;
  --line-2:#dce0e0;
  --bg:#f6f8fa;
  --surface:#ffffff;
  --surface-2:#fafbfc;
  --topbar:#002b4b;
  --footer:#001f38;
  --green:#28a745;
  --red:#e63946;
  --white:#fff;
  --r-btn:8px;
  --r-card:10px;
  --r-chip:6px;
  --shadow-s:0 2px 10px rgba(13,33,54,.06);
  --shadow-m:0 12px 34px rgba(13,33,54,.10);
  --font:'Plus Jakarta Sans','Cairo',system-ui,sans-serif;
