*{box-sizing:border-box;margin:0;padding:0;-webkit-font-smoothing:antialiased;}
html{scroll-behavior:smooth;}
body{font-family:var(--font);color:var(--text);background:var(--white);font-size:15px;line-height:1.6;transition:background .4s;}
[dir="rtl"] body{letter-spacing:0!important;}
img{display:block;max-width:100%;}
a{color:inherit;text-decoration:none;}
h1,h2,h3,h4{color:var(--ink);font-weight:700;line-height:1.2;letter-spacing:-.01em;text-wrap:balance;}
[dir="rtl"] h1,[dir="rtl"] h2,[dir="rtl"] h3,[dir="rtl"] h4{letter-spacing:0;}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px;}
.mono{font-family:var(--mono);}
.i{width:18px;height:18px;stroke-width:2;vertical-align:middle;}

/* ── RTL: flip directional icons so arrows point the correct way in Arabic ── */
[dir="rtl"] [data-lucide="arrow-right"],
[dir="rtl"] [data-lucide="chevron-right"],
[dir="rtl"] [data-lucide="arrow-left"],
[dir="rtl"] [data-lucide="chevron-left"],
[dir="rtl"] [data-lucide="arrow-right-circle"],
[dir="rtl"] [data-lucide="chevron-right-circle"],
[dir="rtl"] [data-lucide="move-right"],
[dir="rtl"] [data-lucide="move-left"]{transform:scaleX(-1);}
/* Don't flip non-directional icons */
[dir="rtl"] [data-lucide="map-pin"],
[dir="rtl"] [data-lucide="map"],
[dir="rtl"] [data-lucide="search"],
[dir="rtl"] [data-lucide="play"],
[dir="rtl"] [data-lucide="maximize-2"],
[dir="rtl"] [data-lucide="external-link"],
[dir="rtl"] [data-lucide="loader-2"]{transform:none;}
/* Also flip the scroll-cue laser line to the left side in RTL */
[dir="rtl"] .scroll-cue{right:auto;left:36px;}
@media(max-width:680px){[dir="rtl"] .scroll-cue{right:auto;left:20px;}}
/* And flip the scroll-cue label direction */
[dir="rtl"] .scroll-cue-label{writing-mode:vertical-rl;}

/* ── motion ─────────────────────────────── */
.rv{opacity:0;transform:translateY(26px);transition:opacity .8s var(--silk),transform .8s var(--silk);will-change:transform;}
.rv.in{opacity:1;transform:none;}
.rv.d1{transition-delay:.08s}.rv.d2{transition-delay:.16s}.rv.d3{transition-delay:.24s}
.rv.d4{transition-delay:.32s}.rv.d5{transition-delay:.4s}
@media(prefers-reduced-motion:reduce){.rv{opacity:1;transform:none;transition:none;}}
/* @keyframes kenburns removed — was causing unwanted hero image movement */
@keyframes pulseDot{0%{box-shadow:0 0 0 0 rgba(0,174,255,.5)}70%{box-shadow:0 0 0 12px rgba(0,174,255,0)}100%{box-shadow:0 0 0 0 rgba(0,174,255,0)}}
