.topbar .tb-left span{display:inline-flex;gap:7px;align-items:center;}
.topbar .tb-right{display:flex;gap:16px;align-items:center;}
.topbar .divider{width:1px;height:16px;background:rgba(255,255,255,.16);}
.topbar .socials{display:flex;gap:14px;}
.topbar .socials .i{width:15px;height:15px;}
.tb-toggle{display:inline-flex;align-items:center;gap:6px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);color:#fff;border-radius:999px;padding:4px 12px;font-family:var(--font);font-size:12px;font-weight:600;cursor:pointer;transition:.2s;}
.tb-toggle:hover{background:rgba(255,255,255,.16);}
.tb-toggle .i{width:13px;height:13px;}

/* ── nav ────────────────────────────────── */
.nav{background:var(--surface);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:600;transition:box-shadow .3s;}
.nav.scrolled{box-shadow:var(--shadow-s);}
.nav .wrap{display:flex;align-items:center;height:76px;gap:34px;}
.brand{display:flex;align-items:center;gap:11px;white-space:nowrap;}
