[data-theme="dark"] .brand .mark{background:#221c0d;color:#e9c176;}
.brand .mark .i{width:22px;height:22px;stroke-width:2.2;}
.brand .mark.logo{background:#fff;padding:0;overflow:hidden;border:1px solid var(--line);}
.brand .mark.logo img{width:100%;height:100%;object-fit:cover;}
[data-theme="dark"] .brand .mark.logo{background:#0a0a0c;border-color:#2a2a2e;}
footer .brand .mark.logo{width:44px;height:44px;}
.brand b{font-size:19px;color:var(--ink);font-weight:800;letter-spacing:-.02em;}
.brand small{display:block;font-family:var(--mono);font-size:9.5px;letter-spacing:.22em;color:var(--muted);text-transform:uppercase;margin-top:1px;white-space:nowrap;}
