.menu{display:flex;gap:26px;margin-inline-start:8px;align-items:center;}
.menu a{font-size:14.5px;font-weight:600;color:var(--ink);display:inline-flex;align-items:center;gap:5px;padding:6px 0;position:relative;white-space:nowrap;}
.menu a.active,.menu a:hover{color:var(--pri);}
.menu a.active::after{content:"";position:absolute;left:0;right:0;bottom:-27px;height:3px;background:var(--pri);border-radius:3px 3px 0 0;}
/* "Open Map" button styled to match nav links */
.nav-link-btn{font-family:var(--font);font-size:14.5px;font-weight:600;color:var(--ink);display:inline-flex;align-items:center;gap:5px;padding:6px 12px;position:relative;white-space:nowrap;background:rgba(0,174,255,.08);border:1px solid rgba(0,174,255,.2);border-radius:8px;cursor:pointer;transition:.2s var(--silk);}
.nav-link-btn:hover{color:var(--pri);background:rgba(0,174,255,.14);border-color:rgba(0,174,255,.4);}
[data-theme="dark"] .nav-link-btn{color:var(--ink);}
.nav-right{margin-inline-start:auto;display:flex;align-items:center;gap:10px;}
.nav-icon{color:var(--ink);position:relative;display:inline-flex;}
.nav-icon .dot{position:absolute;top:-4px;inset-inline-end:-6px;background:var(--pri);color:#fff;font-size:10px;font-weight:700;width:16px;height:16px;border-radius:50%;display:grid;place-items:center;}

/* ── buttons ────────────────────────────── */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-family:var(--font);font-weight:700;font-size:14px;border:none;border-radius:var(--r-btn);padding:11px 20px;cursor:pointer;transition:.2s var(--silk);white-space:nowrap;}
.btn:active{transform:scale(.98);}
.btn-pri{background:var(--pri);color:#fff;box-shadow:0 6px 16px rgba(0,174,255,.32);}
.btn-pri:hover{background:var(--pri-d);transform:translateY(-1px);}
.btn-ghost{background:var(--surface);color:var(--ink);border:1.5px solid var(--line-2);}
.btn-ghost:hover{border-color:var(--pri);color:var(--pri);}
.btn-navy{background:var(--navy);color:#fff;}
.btn-navy:hover{background:#013a63;}

/* ── section shells ─────────────────────── */
section.block{padding:78px 0;background:var(--white);}
[data-theme="dark"] section.block{background:#0d0d0f;}
section.block.well{background:var(--bg);}
.sec-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:36px;gap:24px;}
.eyebrow{font-family:var(--mono);text-transform:uppercase;letter-spacing:.26em;font-size:11.5px;font-weight:600;color:var(--pri);margin-bottom:12px;display:flex;align-items:center;gap:10px;}
[dir="rtl"] .eyebrow{letter-spacing:.05em;font-family:var(--font);}
.eyebrow::before{content:"";width:24px;height:2px;background:var(--pri);}
.sec-head h2{font-size:34px;letter-spacing:-.02em;}
.sec-head p{margin-top:8px;font-size:15.5px;max-width:520px;}
.sec-link{color:var(--pri);font-weight:700;font-size:14px;display:inline-flex;align-items:center;gap:6px;white-space:nowrap;transition:gap .2s;}
.sec-link:hover{gap:10px;}

/* ── tags / property card ───────────────── */
.tag{font-family:var(--mono);text-transform:uppercase;letter-spacing:.08em;font-size:10.5px;font-weight:600;padding:6px 10px;border-radius:var(--r-chip);color:#fff;white-space:nowrap;}
[dir="rtl"] .tag{letter-spacing:.02em;font-family:var(--font);}
.tag.featured{background:var(--pri);}
.tag.sale{background:var(--navy);}
.tag.rent{background:var(--green);}
.tag.hot{background:var(--red);}
.grid-props{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;}
.pcard{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-card);overflow:hidden;transition:.3s var(--silk);display:flex;flex-direction:column;}
.pcard:hover{box-shadow:var(--shadow-m);transform:translateY(-5px);border-color:rgba(0,174,255,.4);}
.pcard .photo{position:relative;height:224px;overflow:hidden;background:var(--bg);}
.pcard .photo img{width:100%;height:100%;object-fit:cover;transition:transform .6s var(--silk);}
.pcard:hover .photo img{transform:scale(1.06);}
.pcard .badges{position:absolute;top:14px;inset-inline-start:14px;display:flex;gap:8px;z-index:3;}
.pcard .heart{position:absolute;top:12px;inset-inline-end:12px;z-index:3;width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.92);display:grid;place-items:center;color:var(--navy);cursor:pointer;transition:.18s;}
.pcard .heart:hover{background:#fff;color:var(--red);transform:scale(1.1);}
.pcard .heart.on{color:var(--red);}
.pcard .price-float{position:absolute;inset-inline-start:14px;bottom:14px;z-index:3;background:rgba(0,43,75,.9);backdrop-filter:blur(6px);color:#fff;padding:8px 13px;border-radius:8px;font-family:var(--mono);font-weight:700;font-size:15px;white-space:nowrap;}
.pcard .ai-score{position:absolute;inset-inline-end:12px;bottom:14px;z-index:3;background:rgba(255,255,255,.94);color:var(--navy);font-family:var(--mono);font-weight:700;font-size:12px;padding:6px 10px;border-radius:8px;display:inline-flex;gap:6px;align-items:center;}
.pcard .ai-score::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--pri);animation:pulseDot 2.4s infinite;}
.pcard .body{padding:18px 18px 0;flex:1;}
.pcard .ptype{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--pri);font-weight:600;}
.pcard h3{font-size:18px;margin:7px 0 6px;}
.pcard h3 a:hover{color:var(--pri);}
.pcard .addr{display:flex;align-items:center;gap:6px;font-size:13.5px;color:var(--text);}
.pcard .addr .i{width:15px;height:15px;color:var(--muted);}
.pcard .specs{display:flex;margin:16px 0 0;border-top:1px solid var(--line);}
