footer .contact-line{display:flex;gap:10px;align-items:flex-start;margin-bottom:14px;}
footer .contact-line .i{color:var(--pri);margin-top:2px;flex:none;}
footer .news{display:flex;margin-top:14px;border:1px solid rgba(255,255,255,.16);border-radius:8px;overflow:hidden;}
footer .news input{flex:1;background:transparent;border:none;color:#fff;padding:12px 14px;font-family:var(--font);font-size:13.5px;outline:none;min-width:0;}
