.bottom-nav{display:none;position:fixed;bottom:0;left:0;right:0;z-index:9990;background:var(--surface);border-top:1px solid var(--line);padding:6px 0 calc(6px + env(safe-area-inset-bottom,0px));justify-content:space-around;align-items:center;box-shadow:0 -4px 20px rgba(0,0,0,.08);}
